<?php
namespace Modules\Ran\Reports;
class CustomerDueReport extends AbstractRanReport{public function title():string{return 'Customer Outstanding';}public function headings():array{return ['Customer ID','Customer','Mobile','Invoice Count','Total','Paid','Balance'];}public function rows(array $f):array{$q=\DB::table('ran_sales as s')->leftJoin('contacts as c','c.id','=','s.customer_contact_id')->whereNull('s.deleted_at')->where('s.balance_amount','>',0)->where('s.business_id',\Modules\Ran\Support\RanContext::businessId());if(!empty($f['location_id']))$q->where('s.location_id',$f['location_id']);return $q->groupBy('s.customer_contact_id','s.customer_name','s.customer_mobile','c.name','c.mobile')->get([\DB::raw('COALESCE(s.customer_contact_id,0) customer_id'),\DB::raw('COALESCE(c.name,s.customer_name) customer'),\DB::raw('COALESCE(c.mobile,s.customer_mobile) mobile'),\DB::raw('COUNT(*) invoice_count'),\DB::raw('SUM(s.total_amount) total'),\DB::raw('SUM(s.paid_amount) paid'),\DB::raw('SUM(s.balance_amount) balance')])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Total'=>array_sum(array_column($rows,'total')),'Paid'=>array_sum(array_column($rows,'paid')),'Balance'=>array_sum(array_column($rows,'balance'))];}}
